// original.cs — a quotes API wired straight to a hand-rolled static
// singleton (QuoteRepo.Instance), an inline `new EmailStub()`, and
// DateTime.Now. It serves perfectly. It also cannot be tested: every
// dependency is hard-wired, so the "tests" at the bottom of this file hit
// the ONE real repo — run them and watch them pollute each other.
//
// Run:    dotnet run csharp/18-dependency-injection/original.cs
// Tests:  dotnet run csharp/18-dependency-injection/original.cs -- test
// Then:   curl http://localhost:5018/quotes

using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/quotes", () => Results.Json(QuoteRepo.Instance.All()));

app.MapGet("/quotes/daily", () =>
{
    // "Quote of the day" — but WHICH day comes from DateTime.Now, grabbed
    // out of thin air. There is no way to ask "what does this return on
    // March 3rd?" without changing your computer's clock.
    var all = QuoteRepo.Instance.All();
    var pick = all[DateTime.Now.DayOfYear % all.Count];
    return Results.Json(pick);
});

app.MapPost("/quotes", (JsonElement body) =>
{
    if (!body.TryGetProperty("text", out var t) || t.ValueKind != JsonValueKind.String
        || t.GetString()!.Trim().Length == 0)
        return Results.Json(new { error = "text must not be empty" }, statusCode: 400);

    var author = "anonymous";
    if (body.TryGetProperty("author", out var a) && a.ValueKind == JsonValueKind.String
        && a.GetString()!.Trim().Length > 0)
        author = a.GetString()!.Trim();

    var quote = new Quote(t.GetString()!.Trim(), author);
    QuoteRepo.Instance.Add(quote);

    // `new` right here, welded in: EVERY caller of this endpoint sends a
    // real notification. A test of "adding a quote works" spams the
    // "email" console too — there is no seam to slip a fake through.
    new EmailStub().Send($"new quote by {quote.Author}: \"{quote.Text}\"");

    return Results.Json(quote, statusCode: 201);
});

// ---------------------------------------------------------------------------
// The "tests". They live at the bottom of the app file because the logic
// can't be reached from anywhere else — and they share the one static repo.
// ---------------------------------------------------------------------------
if (args.Contains("test"))
{
    Console.WriteLine("test 1: adding a quote bumps the count");
    var before = QuoteRepo.Instance.All().Count;
    QuoteRepo.Instance.Add(new Quote("Talk is cheap. Show me the code.", "Linus Torvalds"));
    Console.WriteLine(QuoteRepo.Instance.All().Count == before + 1
        ? "  ok  count went up by one"
        : "  FAIL count did not go up");

    Console.WriteLine("test 2: a fresh app has exactly the 3 seeded quotes");
    // FAILS — test 1 already added a 4th quote to the ONE AND ONLY repo.
    // There is no way to get a fresh one: the constructor is private and
    // Instance is readonly. The tests are welded together through shared
    // state, so their ORDER changes their results.
    Console.WriteLine(QuoteRepo.Instance.All().Count == 3
        ? "  ok  exactly the 3 seeded quotes"
        : $"  FAIL expected 3 quotes, found {QuoteRepo.Instance.All().Count} (test 1 polluted the shared singleton!)");

    Console.WriteLine("test 3: the daily quote for a known date is predictable");
    Console.WriteLine("  SKIP  impossible to write — DateTime.Now is hard-wired inside the endpoint");
    return;
}

app.Run("http://localhost:5018");

record Quote(string Text, string Author);

// The hand-rolled singleton: ONE instance, reachable from anywhere,
// replaceable by nothing. (cs#10 built plug-ins to AVOID exactly this.)
class QuoteRepo
{
    public static readonly QuoteRepo Instance = new();
    private QuoteRepo() { }   // nobody else may construct one — not even a test

    private readonly List<Quote> _quotes = new()
    {
        new Quote("Simplicity is the soul of efficiency.", "Austin Freeman"),
        new Quote("Make it work, make it right, make it fast.", "Kent Beck"),
        new Quote("Programs must be written for people to read.", "Harold Abelson"),
    };

    public List<Quote> All() => _quotes;
    public void Add(Quote quote) => _quotes.Add(quote);
}

class EmailStub
{
    public void Send(string message) => Console.WriteLine($"[email] {message}");
}

# 🏋️ Practice: Dependency Injection

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. List the authors (warm-up)

Add `GET /quotes/authors` returning a sorted list of distinct authors (case-insensitively distinct —
"ada" and "Ada" are one person). The logic goes in `QuoteService`, tested with a fresh world.
*Practices:* a service method over the injected repo + one declared-need endpoint.
**Hint:** `Distinct(StringComparer.OrdinalIgnoreCase)` then `OrderBy(a => a)`.
**Check offline:** `Check.Equal("ada,bob", string.Join(",", svc.Authors()), "distinct + sorted")` passes;
`curl http://localhost:5018/quotes/authors` → `["ada","bob",...]`.

### ⭐⭐ 2. A weekly quote (core)

Add `GET /quotes/weekly`: the same quote all week, rotating weekly. Rule: week number =
`(DayOfYear - 1) / 7` (Jan 1–7 is week 0, Jan 8–14 week 1, ...), pick `week % count`. Empty repo → 404.
*Practices:* a clock-dependent rule made testable purely because `IClock` is injected.
**Hint:** mirror `Daily()`; the tests set `clock.Now` to Jan 1, Jan 7, and Jan 8 and watch the pick change only once.
**Check offline:** add these Check tests — they should pass (3 seeded quotes):
`clock.Now = new DateTime(2026, 1, 7); Check.Equal("A", svc.Weekly()!.Text, "day 7 is still week 0");`
`clock.Now = new DateTime(2026, 1, 8); Check.Equal("B", svc.Weekly()!.Text, "day 8 starts week 1");`

### ⭐⭐ 3. Grow the seam: deleting quotes (core)

Add `bool Remove(string text)` to `IQuoteRepo` (true if something was deleted; match text
case-insensitively), implement it in `InMemoryQuoteRepo`, expose
`QuoteService.Remove(string? text)` that rejects blank input, and map
`DELETE /quotes?text=...` → 204 or 404. Notice who forces you to update the repo class: the compiler.
*Practices:* evolving an interface — every implementer must follow, and the tests prove the rule.
**Hint:** `_quotes.RemoveAll(q => string.Equals(q.Text, text, StringComparison.OrdinalIgnoreCase)) > 0`.
**Check offline:** `Check.True(!svc.Remove("   "), "blank text removes nothing")` passes;
`curl -i -X DELETE "http://localhost:5018/quotes?text=Ship%20it."` → `404` before adding it, `204` after.

### ⭐⭐ 4. One notification, many places: CompositeNotifier (core)

Write `CompositeNotifier : INotifier` that forwards each message to *every* notifier it was built
with, plus a `FileNotifier` appending lines to `notifications.log`. Register the composite so a POST
both prints to the console *and* appends to the file — without touching `QuoteService` or any endpoint.
*Practices:* composing implementations behind one interface; the composition root as the only edit site.
**Hint:** `public CompositeNotifier(params INotifier[] targets)` makes wiring read nicely.
**Check offline:** add this Check test — it should pass:
`var f1 = new FakeNotifier(); var f2 = new FakeNotifier(); new CompositeNotifier(f1, f2).Notify("x"); Check.Equal(1, f2.Sent.Count, "both targets heard it");`
Then POST a quote and `cat notifications.log`.

### ⭐⭐⭐ 5. Randomness is a dependency too (challenge)

Add `GET /quotes/random`. The trap: `new Random()` inside the service makes the pick untestable —
exactly the `DateTime.Now` disease with a different clock. Introduce
`IRandom { int Next(int maxExclusive); }` with a `SystemRandom` implementation, inject it as a fourth
constructor parameter, and write a `FakeRandom` whose picks are scripted so the tests are exact.
Update `Make` in Tests.cs and register `SystemRandom` in Program.cs.
*Practices:* recognizing a hidden input and cutting a brand-new seam for it, end to end.
**Hint:** `FakeRandom` can hold a settable `NextValue` and return `NextValue % maxExclusive`.
**Check offline:** add this Check test — it should pass:
`rng.NextValue = 2; Check.Equal("C", svc.Random()!.Text, "the pick is exactly what the fake dictated");`

## Solutions

### 1. Authors

```csharp
// QuoteService.cs
public IReadOnlyList<string> Authors() =>
    _repo.All()
        .Select(q => q.Author)
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .OrderBy(a => a)
        .ToList();

// Program.cs
app.MapGet("/quotes/authors", (QuoteService svc) => svc.Authors());
```

WHY: the endpoint declares its need (`QuoteService`) and the container assembles the whole
repo-clock-notifier graph behind it. Because the rule reads only `IQuoteRepo`, the test needs nothing
but a seeded `InMemoryQuoteRepo` — no container in sight, which is the point of constructor injection.

### 2. Weekly

```csharp
// QuoteService.cs
/// Same quote all week; a new pick every 7 days. Testable for the same
/// reason Daily() is: the date is an injected input, not a global.
public Quote? Weekly()
{
    var all = _repo.All();
    if (all.Count == 0) return null;
    var week = (_clock.Now.DayOfYear - 1) / 7;   // Jan 1-7 -> 0, Jan 8-14 -> 1, ...
    return all[week % all.Count];
}

// Program.cs
app.MapGet("/quotes/weekly", (QuoteService svc) =>
    svc.Weekly() is Quote q ? Results.Ok(q) : Results.NotFound());

// Tests.cs — inside a block using Make(...)
var svc = Make(out _, out var clock, out _);
clock.Now = new DateTime(2026, 1, 1);
Check.Equal("A", svc.Weekly()!.Text, "day 1 is week 0 -> index 0");
clock.Now = new DateTime(2026, 1, 7);
Check.Equal("A", svc.Weekly()!.Text, "day 7 is still week 0");
clock.Now = new DateTime(2026, 1, 8);
Check.Equal("B", svc.Weekly()!.Text, "day 8 starts week 1 -> index 1");
clock.Now = new DateTime(2026, 1, 22);
Check.Equal("A", svc.Weekly()!.Text, "week 3 wraps: 3 % 3 = 0");
```

WHY: the `- 1` matters — `DayOfYear` is 1-based, and without it Jan 7 and Jan 8 would land in the same
week (7/7 == 8/7 == 1). That off-by-one is invisible to manual testing and a one-line FakeClock test.
Integer division + modulo is the same clock math `Daily()` uses, one level up.

### 3. Remove

```csharp
// Quotes.cs — the interface grows...
public interface IQuoteRepo
{
    IReadOnlyList<Quote> All();
    void Add(Quote quote);
    bool Remove(string text);
}

// ...and the compiler now refuses to build until InMemoryQuoteRepo complies:
public bool Remove(string text) =>
    _quotes.RemoveAll(q => string.Equals(q.Text, text, StringComparison.OrdinalIgnoreCase)) > 0;

// QuoteService.cs — the rule: blank input never reaches the repo
public bool Remove(string? text) =>
    !string.IsNullOrWhiteSpace(text) && _repo.Remove(text.Trim());

// Program.cs — `string text` (non-nullable) makes ?text= required: missing -> automatic 400
app.MapDelete("/quotes", (QuoteService svc, string text) =>
    svc.Remove(text) ? Results.NoContent() : Results.NotFound());
```

WHY: changing the interface is a *contract* change, so the compiler walks you to every implementation
— that's the safety net statics never give. The service still owns validation (blank text is a
decision, not storage), and the endpoint translates the bool into 204/404 exactly like cs#16 taught.

### 4. CompositeNotifier

```csharp
// Notifier.cs
public class FileNotifier : INotifier
{
    private readonly string _path;
    public FileNotifier(string path) => _path = path;
    public void Notify(string message) =>
        File.AppendAllText(_path, $"{message}{Environment.NewLine}");
}

public class CompositeNotifier : INotifier
{
    private readonly INotifier[] _targets;
    public CompositeNotifier(params INotifier[] targets) => _targets = targets;
    public void Notify(string message)
    {
        foreach (var target in _targets) target.Notify(message);
    }
}

// Program.cs — the ONLY line that changes
builder.Services.AddSingleton<INotifier>(
    new CompositeNotifier(new ConsoleNotifier(), new FileNotifier("notifications.log")));
```

WHY: the composite is itself an `INotifier`, so neither `QuoteService` nor any endpoint can tell one
listener from five — fan-out became a wiring decision, made in the composition root. The Check test
proves the fan-out with two `FakeNotifier`s, no console and no filesystem involved.

### 5. IRandom

```csharp
// Clock.cs (or a new Random.cs) — the new seam
public interface IRandom { int Next(int maxExclusive); }

public class SystemRandom : IRandom
{
    private readonly Random _random = new();
    public int Next(int maxExclusive) => _random.Next(maxExclusive);
}

// QuoteService.cs — fourth ingredient
private readonly IRandom _random;
public QuoteService(IQuoteRepo repo, IClock clock, INotifier notifier, IRandom random)
{
    _repo = repo; _clock = clock; _notifier = notifier; _random = random;
}
public Quote? Random()
{
    var all = _repo.All();
    if (all.Count == 0) return null;
    return all[_random.Next(all.Count)];
}

// Program.cs
builder.Services.AddSingleton<IRandom, SystemRandom>();
app.MapGet("/quotes/random", (QuoteService svc) =>
    svc.Random() is Quote q ? Results.Ok(q) : Results.NotFound());

// Tests.cs — the fake, plus Make grows a line
public class FakeRandom : IRandom
{
    public int NextValue { get; set; }
    public int Next(int maxExclusive) => NextValue % maxExclusive;
}
// in Make: rng = new FakeRandom(); return new QuoteService(repo, clock, notifier, rng);

var svc = Make(out _, out _, out _, out var rng);
rng.NextValue = 2;
Check.Equal("C", svc.Random()!.Text, "the pick is exactly what the fake dictated");
rng.NextValue = 0;
Check.Equal("A", svc.Random()!.Text, "and it changes when the fake does");
```

WHY: "random" and "now" are the same kind of thing — inputs your code doesn't control — so they get
the same treatment: an interface, a real implementation registered once, a fake in tests. The `%`
inside `FakeRandom` keeps scripted values safe for any list size. Miss the registration and the
container fails loudly at startup naming `IRandom` — the missing-recipe error, now working for you.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// Time as a dependency. "What day is it?" is an INPUT to the daily-quote
// rule — hard-wiring DateTime.Now hides that input and makes the rule
// untestable. Behind an interface, tests can make it any day they like.
public interface IClock
{
    DateTime Now { get; }
}

public class SystemClock : IClock
{
    public DateTime Now => DateTime.Now;
}

// The original did `new EmailStub().Send(...)` INSIDE the endpoint — no way
// to fake it. As an interface, production gets the console version and
// tests get a FakeNotifier that just records what would have been sent.
public interface INotifier
{
    void Notify(string message);
}

public class ConsoleNotifier : INotifier
{
    public void Notify(string message) => Console.WriteLine($"[notify] {message}");
}

// Program.cs — the COMPOSITION ROOT: the one place that decides which real
// implementation each interface gets. Everywhere else just declares needs.

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);

// Register once, in one place. Lifetimes:
//   Singleton — ONE instance for the whole app (the repo HOLDS our data,
//               so it must be shared; same for the clock and notifier).
//   Scoped    — one instance PER REQUEST (fits per-request workers like
//               QuoteService; see LEARN.md for the story).
//   Transient — a fresh instance EVERY time anyone asks.
builder.Services.AddSingleton<IQuoteRepo>(new InMemoryQuoteRepo(new[]
{
    new Quote("Simplicity is the soul of efficiency.", "Austin Freeman"),
    new Quote("Make it work, make it right, make it fast.", "Kent Beck"),
    new Quote("Programs must be written for people to read.", "Harold Abelson"),
}));
builder.Services.AddSingleton<IClock, SystemClock>();
builder.Services.AddSingleton<INotifier, ConsoleNotifier>();
builder.Services.AddScoped<QuoteService>();

var app = builder.Build();

// Endpoints DECLARE what they need as parameters; the container supplies it.
// No statics, no `new` — swap a registration above and every endpoint
// changes behavior without editing a single line below.
app.MapGet("/quotes", (QuoteService svc) => svc.All());

app.MapGet("/quotes/daily", (QuoteService svc) =>
    svc.Daily() is Quote q ? Results.Ok(q) : Results.NotFound());

app.MapPost("/quotes", (QuoteService svc, QuoteInput body) =>
    svc.Add(body.Text, body.Author) is Quote q
        ? Results.Created("/quotes", q)
        : Results.BadRequest(new { error = "text must not be empty" }));

app.Run("http://localhost:5018");

public record Quote(string Text, string Author);

// What clients send when adding a quote.
public record QuoteInput(string? Text, string? Author);

// The SEAM (cs#10's plug-in idea): anything that stores quotes. The service
// depends on this interface, never on a concrete class — so tests hand it a
// fresh in-memory repo and production could hand it a database tomorrow.
public interface IQuoteRepo
{
    IReadOnlyList<Quote> All();
    void Add(Quote quote);
}

public class InMemoryQuoteRepo : IQuoteRepo
{
    private readonly List<Quote> _quotes;

    // Constructible by ANYONE, seeded with whatever the caller wants —
    // compare the original's private constructor + static Instance.
    public InMemoryQuoteRepo(IEnumerable<Quote>? seed = null)
        => _quotes = seed?.ToList() ?? new List<Quote>();

    public IReadOnlyList<Quote> All() => _quotes;
    public void Add(Quote quote) => _quotes.Add(quote);
}

// QuoteService — the rules, with every dependency handed in through the
// constructor ("constructor injection"). It never news-up or reaches for a
// static: storage, time, and notifications all arrive as interfaces, so
// tests can swap in fakes for any of them.
public class QuoteService
{
    private readonly IQuoteRepo _repo;
    private readonly IClock _clock;
    private readonly INotifier _notifier;

    public QuoteService(IQuoteRepo repo, IClock clock, INotifier notifier)
    {
        _repo = repo;
        _clock = clock;
        _notifier = notifier;
    }

    public IReadOnlyList<Quote> All() => _repo.All();

    /// Same date → same quote all day; the date comes from the injected
    /// clock, which is the only reason this rule is testable.
    public Quote? Daily()
    {
        var all = _repo.All();
        if (all.Count == 0) return null;
        return all[_clock.Now.DayOfYear % all.Count];
    }

    /// Returns the stored quote, or null when the text is missing/blank.
    /// A blank author becomes "anonymous". Success sends one notification.
    public Quote? Add(string? text, string? author)
    {
        if (string.IsNullOrWhiteSpace(text)) return null;
        var quote = new Quote(
            text.Trim(),
            string.IsNullOrWhiteSpace(author) ? "anonymous" : author.Trim());
        _repo.Add(quote);
        _notifier.Notify($"new quote by {quote.Author}: \"{quote.Text}\"");
        return quote;
    }
}

// Tests.cs — every test builds its OWN service from a fresh repo and fakes.
// No shared state, no static Instance, no real clock, no real notifications.
// Run these in any order, any number of times: same results. That property
// is exactly what the original's singleton made impossible.

// FAKES: tiny stand-ins that implement the same interfaces production uses.
public class FakeClock : IClock
{
    public DateTime Now { get; set; } = new DateTime(2026, 1, 1);
}

public class FakeNotifier : INotifier
{
    public List<string> Sent { get; } = new();
    public void Notify(string message) => Sent.Add(message);
}

public static class Tests
{
    static readonly Quote[] Seed =
    {
        new("A", "author-a"),   // index 0
        new("B", "author-b"),   // index 1
        new("C", "author-c"),   // index 2
    };

    // Each call builds a completely independent world.
    static QuoteService Make(out InMemoryQuoteRepo repo, out FakeClock clock, out FakeNotifier notifier, bool seeded = true)
    {
        repo = new InMemoryQuoteRepo(seeded ? Seed : null);
        clock = new FakeClock();
        notifier = new FakeNotifier();
        return new QuoteService(repo, clock, notifier);
    }

    public static int Run()
    {
        Console.WriteLine("the original's two poisoned tests — now independent");
        {
            var svc = Make(out var repo, out _, out _);
            svc.Add("Talk is cheap. Show me the code.", "Linus Torvalds");
            Check.Equal(4, repo.All().Count, "test 1: adding a quote bumps the count");
        }
        {
            var svc = Make(out var repo, out _, out _);
            Check.Equal(3, repo.All().Count, "test 2: a fresh world has exactly the seeded quotes (no pollution possible)");
        }

        Console.WriteLine("QuoteService.Add — rules");
        {
            var svc = Make(out var repo, out _, out _);
            var q = svc.Add("  Stay hungry.  ", "  Stewart Brand ");
            Check.Equal("Stay hungry.", q!.Text, "text is trimmed");
            Check.Equal("Stewart Brand", q.Author, "author is trimmed");
            Check.Equal(null, svc.Add("", "X"), "empty text is rejected");
            Check.Equal(null, svc.Add("   ", "X"), "whitespace text is rejected");
            Check.Equal(null, svc.Add(null, "X"), "missing text is rejected");
            Check.Equal(4, repo.All().Count, "rejected quotes never reached the repo");
            Check.Equal("anonymous", svc.Add("No author here", null)!.Author, "a missing author becomes \"anonymous\"");
        }

        Console.WriteLine("QuoteService.Add — notifications (via FakeNotifier)");
        {
            var svc = Make(out _, out _, out var notifier);
            svc.Add("Ship it.", "ada");
            Check.Equal(1, notifier.Sent.Count, "a successful add sends exactly one notification");
            Check.True(notifier.Sent[0].Contains("ada"), "the notification names the author");
            svc.Add("", "ada");
            Check.Equal(1, notifier.Sent.Count, "a REJECTED add sends nothing");
        }

        Console.WriteLine("QuoteService.Daily — time is just another input (via FakeClock)");
        {
            var svc = Make(out _, out var clock, out _);
            clock.Now = new DateTime(2026, 1, 1);   // DayOfYear 1 → 1 % 3 → index 1
            Check.Equal("B", svc.Daily()!.Text, "Jan 1 picks index 1");
            Check.Equal("B", svc.Daily()!.Text, "same day, same quote — deterministic");
            clock.Now = new DateTime(2026, 1, 2);   // 2 % 3 → index 2
            Check.Equal("C", svc.Daily()!.Text, "Jan 2 picks index 2");
            clock.Now = new DateTime(2026, 1, 3);   // 3 % 3 → index 0
            Check.Equal("A", svc.Daily()!.Text, "Jan 3 wraps around to index 0");
            // The original's test 3 printed SKIP here: DateTime.Now was
            // hard-wired, so "what happens on Jan 3?" was unanswerable.
        }
        {
            var svc = Make(out _, out _, out _, seeded: false);
            Check.Equal(null, svc.Daily(), "an empty repo has no daily quote (endpoint: 404, not a crash)");
        }

        return Check.Summary();
    }
}
